{"tool":"brick.build","input":{"code":"script({title:"Little Beacon Toll Gate",description:"A clear stone arch with a red signal beacon beside a yellow guard hut with an overhanging pitched roof. Exactly 16 inventory parts.",palette:{stone:"light bluish grey",coping:"dark bluish grey",wall:"yellow",roof:"dark blue",signal:"trans red",mount:"black"}});
const part=(id,at,colour,turn=0)=>place({part:id,at,colour,turn});
const pier=x=>[part("3001.dat",[x,0,0],"stone",90),part("3068b.dat",[x,3,0],"coping")];
section("Gate and signal — 10 parts",[
  ...[0,4].flatMap(pier),
  ...[2,3].map(z=>part("3659.dat",[1,3,z],"stone")),
  part("3068b.dat",[2,6,2],"coping"),
  ...range(3).map(i=>part("3024.dat",[1,6+i,2],i===0?"mount":"signal"))
]);
const hutX=8;
const roofHalf=(z,turn)=>[0,2].map(dx=>part("3039.dat",[hutX+dx,6,z],"roof",turn));
section("Guard hut — 6 parts",[
  ...range(2).map(i=>part("3001.dat",[hutX,3*i,1],"wall")),
  ...roofHalf(0,0),
  ...roofHalf(2,180)
]);","seed":1}}
